import json, hashlib
from pathlib import Path
from collections import defaultdict
import numpy as np
root=Path.cwd(); work=root/'work/asi-evidence'; data=root/'researches/nested-attr-vector-search/2026-11-08-exps/data'
load=lambda p:[json.loads(line) for line in p.read_text().splitlines() if line.strip()]
protocol=json.loads((data/'navigation-protocol.json').read_text())
reference=load(work/'navigation-reference.jsonl'); rep=load(work/'navigation-representative.jsonl'); high=load(work/'navigation-hnsw.jsonl')
assert len(reference)==len(rep)==len(high)==1400
common_fields=sorted(reference[0])
for b,a in zip(reference,rep):
    assert all(a[k]==b[k] for k in common_fields)
graphs_a={g['concept']:g for g in load(work/'navigation-asi-graphs.jsonl')}
graphs_n={g['concept']:g for g in load(work/'navigation-nodeann-graphs.jsonl')}
assert graphs_a==graphs_n and len(graphs_a)==768
owner=np.loadtxt(root/'work/dag-scope/workload-run1/objects.txt',dtype=np.int32)
base=np.fromfile(root/'work/dag-ann/recon.bin',dtype=np.float32).reshape(-1,128)
queries=np.fromfile(root/'work/dag-ann/queries.bin',dtype=np.float32).reshape(-1,128)
members=defaultdict(list)
for i,c in enumerate(owner): members[int(c)].append(i)
repq={r['qi']:r for r in rep if r['ef']==10}; highq={r['qi']:r for r in high if r['ef']==10}
replays=[]
for qi in range(200):
    seeds=[]; requests=[]; slots=0
    owners=[int(owner[item]) for item in repq[qi]['seed_nodes']]
    assert owners==[int(owner[item]) for item in highq[qi]['seed_nodes']]
    for concept in owners:
        g=graphs_n[concept]; ids=np.asarray(members[concept],dtype=np.int32)
        assert [n['label'] for n in g['nodes']]==list(range(len(ids)))
        scores=np.zeros(len(ids),dtype=np.float32)
        for dim in range(128):
            delta=queries[qi,dim]-base[ids,dim]; scores+=delta*delta
        current=g['entry']; distance=scores[current]; requests.append(int(ids[current]))
        for level in range(g['maxlevel'],0,-1):
            changed=True
            while changed:
                changed=False; neighbors=g['nodes'][current]['levels'][level]; slots+=len(neighbors)
                for neighbor in neighbors:
                    requests.append(int(ids[neighbor]))
                    if scores[neighbor]<distance:
                        current=neighbor; distance=scores[neighbor]; changed=True
        seeds.append(int(ids[current]))
    actual=highq[qi]
    assert seeds==actual['seed_nodes'] and requests==actual['seed_evaluated']
    assert slots==actual['upper_adjacency_slots'] and len(set(requests))==actual['upper_distance_calls']
    replays.append(dict(qi=qi,seed_nodes=seeds,score_request_sha256=hashlib.sha256(json.dumps(requests,separators=(',',':')).encode()).hexdigest(),upper_distance_calls=len(set(requests)),upper_slots=slots,exact_match=True))
archive=load(data/'navigation-per-query.jsonl')
archived={(r['variant'],r['ef'],r['perN'],r['qi']):r for r in archive}
assert len(archive)==len(archived)==3600
raw=[('representative',rep),('hnsw',high)]+[('NodeANN',load(work/f'navigation-nodeann-{n}.jsonl')) for n in [5,10,15,20]]
for variant,rows in raw:
    for row in rows:
        saved=archived[(variant,row['ef'],row.get('perN'),row['qi'])]; oracle=repq[row['qi']]
        assert saved['returned']==row['returned'] and len(saved['returned'])==len(set(saved['returned']))
        assert saved['fp_hits']==len(set(row['returned'])&set(oracle['fp_top']))
        assert saved['pq_hits']==len(set(row['returned'])&set(oracle['pq_top']))
        for field in ['distance_calls','adjacency_slots','upper_distance_calls','upper_adjacency_slots','seed_nodes']:
            assert saved[field]==row.get(field)
fixture=load(data/'navigation-fixture-traces.jsonl'); spec=protocol['fixture']; children=defaultdict(list)
for child,parent in spec['edges_child_parent']: children[parent].append(child)
for row in fixture:
    scope=set(); stack=list(spec['query_attributes'][row['qi']])
    while stack:
        c=stack.pop()
        if c not in scope: scope.add(c); stack.extend(children[c])
    assert all(spec['owners'][item] in scope for item in row['returned'])
    assert len(row['returned'])==len(set(row['returned']))
    if row['qi']==6: assert row['returned']==[36]
    if row['variant']!='NodeANN':
        assert row['distance_calls']==len(set(row['evaluated'])|set(row['seed_evaluated']))
        assert len(row['expanded'])==len(set(row['expanded']))
by_key={(r['variant'],r.get('ef2'),r['ef'],r['qi']):r for r in fixture}
for variant in ['representative','hnsw']:
    for ef2 in [1,16]:
        for ef in [5,10,40]:
            assert by_key[(variant,ef2,ef,2)]['returned']==by_key[(variant,ef2,ef,3)]['returned']
node_rows={r['qi']:r for r in fixture if r['variant']=='NodeANN'}
result=dict(native_graphs_equal=768,reference_common_fields=common_fields,reference_equal_rows=1400,archive_matches_raw_rows=3600,upper_replay_queries=200,upper_replay_owner_entries=sum(len(r['seed_nodes']) for r in replays),upper_replay=replays,fixture_rows=79,fixture_scope_unique_singleton=True,asi_duplicate_OR_same_returned_IDs=True,nodeann_duplicate_OR_same_returned_IDs=set(node_rows[2]['returned'])==set(node_rows[3]['returned']),fixture_limit='All-zero distances: NodeANN may return different valid tied ID sets for duplicate OR input. This check does not assert cross-method tie equivalence. Only first-round nonempty ASI traces are serialized.')
print(json.dumps(result))
